// 测试用 dsh-llm 最小替身：提供与主仓库 HarnessError 相同的契约
// （message/code/cause 链、name 默认类名）。真实环境由 DSH 通过 profile
// 的 require 上下文提供，与主进程同一实例。
class HarnessError extends Error {
  constructor(message, code, options) {
    super(message, options)
    this.code = code
    this.name = new.target.name
  }
}

module.exports = { HarnessError }